#!/usr/bin/env node
// GENERATED by tools/shared-checks.mjs in the GaugeWright repository, which owns
// the shared check harness. Do not edit this file: it verifies itself against the
// digest below, so a local edit fails this repository's own gate. Change the
// source there and re-render.
//
//   node scripts/check-shared-harness.mjs
//
// It answers two questions the shell cannot ask about itself. First, whether
// `scripts/prerequisite.sh` is still the file this repository was given. That
// helper decides what the bar does about an absent tool — skip and say so, or
// refuse — and an edit to it is an edit to what the gate means. A digest here
// fails close to whoever made it, rather than waiting for a cross-repository
// sweep from the owning repository to notice.
//
// Second, whether the word that helper reads actually REACHES it on the Buck2
// path (DR-0132). The helper settles what a section does with the word and
// settles nothing about whether the word arrives, and those are different
// facts: whipplescript-src computed the word, exported it for the direct path,
// and passed only the run nonce to Buck2 for three days. The rule defaults an
// absent `green_bar.prerequisites` to `required`, so the one host that takes
// the Buck2 path ran a bar stricter than this helper documents — an absent
// tool failing it with a message about the host instead of skipping and naming
// the remedy, which is the failure DR-0127 was written against.

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const SOURCE_DIGEST = "5efc91f22149d5427ae99537bc14f82bfa2146eb016561320612ec5681a976d1";
const HARNESS_DIGEST = "d9ac8f31822b9c3b5bc5765c8ae5108313d2c437cf58327e6386bd3c58160340";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const HARNESS_PATH = "scripts/prerequisite.sh";

const failures = [];

const harnessAt = path.join(repoRoot, HARNESS_PATH);
if (!fs.existsSync(harnessAt)) {
  failures.push(`${HARNESS_PATH} is missing; it is owned by the GaugeWright repository`);
} else {
  const have = crypto.createHash("sha256").update(fs.readFileSync(harnessAt)).digest("hex");
  if (have !== HARNESS_DIGEST) {
    failures.push(
      `${HARNESS_PATH} does not match what was rendered here; `
        + "it is owned by the GaugeWright repository",
    );
  }
}

// Every buck2 invocation in the bar must name the word. A dispatcher wraps its
// invocation across lines — all four that get this right are written that way —
// so continuations are joined before looking: matching line by line would miss
// a flag one line down and fail every correct dispatcher. Comment lines are
// skipped, because a bar's comments legitimately quote the command they run.
//
// The limit is honest: this reads shell text, which is the brittleness `covers`
// was introduced to escape. A flag behind a variable, or built up in a string,
// satisfies this while delivering nothing. DR-0132 records that if that ever
// happens the answer is for the rule to refuse an absent word outright, the way
// it already refuses an absent `green_bar.run`.
function invocationsMissingWord(dispatcher) {
  return dispatcher
    .replace(/\\\r?\n[ \t]*/g, " ")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("#"))
    .filter((line) => /\bbuck2 build\b/.test(line))
    .filter((line) => !line.includes("green_bar.prerequisites"));
}

const DISPATCH_PATH = "scripts/check.sh";
const dispatchAt = path.join(repoRoot, DISPATCH_PATH);
if (fs.existsSync(dispatchAt)) {
  for (const invocation of invocationsMissingWord(fs.readFileSync(dispatchAt, "utf8"))) {
    failures.push(
      `${DISPATCH_PATH} dispatches through Buck2 without naming green_bar.prerequisites, `
        + `so this bar is stricter than ${HARNESS_PATH} documents (DR-0132): ${invocation}`,
    );
  }
}

// Both placeholders are assembled rather than written, so that each line the
// renderer substitutes appears exactly once in this file. Spelling one out here
// too would give the substitution a second target, and rewriting both is how a
// generated check ends up comparing a digest against itself and passing
// unconditionally.
const SOURCE_PLACEHOLDER = "__EXPECTED" + "_DIGEST__";
const HARNESS_PLACEHOLDER = "__HARNESS" + "_DIGEST__";

// The digest is of the template as it is written in the owning repository, with
// both placeholders intact — so reversing both substitutions reconstructs it,
// and any change to this file's own text is caught.
const self = fs.readFileSync(fileURLToPath(import.meta.url), "utf8");
const selfDigest = crypto
  .createHash("sha256")
  .update(
    self
      .replace(
        `const SOURCE_DIGEST = "${SOURCE_DIGEST}";`,
        `const SOURCE_DIGEST = "${SOURCE_PLACEHOLDER}";`,
      )
      .replace(
        `const HARNESS_DIGEST = "${HARNESS_DIGEST}";`,
        `const HARNESS_DIGEST = "${HARNESS_PLACEHOLDER}";`,
      ),
    "utf8",
  )
  .digest("hex");
if (selfDigest !== SOURCE_DIGEST) {
  failures.push("this check has been edited locally; it is generated by the GaugeWright repository");
}

if (failures.length > 0) {
  for (const f of failures) console.error(`shared harness: ${f}`);
  process.exit(1);
}

console.log(
  `shared harness check passed at sha256:${SOURCE_DIGEST.slice(0, 12)}… `
    + `(${HARNESS_PATH} at sha256:${HARNESS_DIGEST.slice(0, 12)}…, `
    + `and every buck2 invocation in ${DISPATCH_PATH} names the word).`,
);
